'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function rich(value){
 const math=[],prefix='HUBMATH'+crypto.randomUUID().replaceAll('-','');
 const source=String(value||'').replace(/\$\$[\s\S]+?\$\$|\\\[[\s\S]+?\\\]|\\\([\s\S]+?\\\)|(?<!\\)\$[^\n$]+?\$/g,m=>{math.push(m);return prefix+(math.length-1)+'END'});
 const html=DOMPurify.sanitize(marked.parse(source,{breaks:true}),{ALLOWED_TAGS:['p','br','strong','em','del','a','h1','h2','h3','h4','h5','h6','blockquote','pre','code','ul','ol','li','hr','table','thead','tbody','tr','th','td'],ALLOWED_ATTR:['href','title']});
 const container=document.createElement('div');container.innerHTML=html.replace(new RegExp(prefix+'(\\d+)END','g'),(_,n)=>esc(math[+n]));
 renderMathInElement(container,{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false},{left:'$',right:'$',display:false}],throwOnError:false,trust:false,maxExpand:1000,strict:'ignore'});
 container.querySelectorAll('a').forEach(a=>{a.rel='noopener noreferrer'});return container.innerHTML;
}

let state, subjects=[],topics=[],user,csrf,dirty=false,toastTimer;
const kinds={work:'Работа',photo:'Фото',task:'Задача',idea:'Идея'}, roles={user:'Участник',moderator:'Модератор',admin:'Администратор'};
const date=v=>v?new Date(v).toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}):'Дата не сохранена';
const link=(url,label)=>`<a href="${esc(url)}">${esc(label)}</a>`;
const authorLink=(name,deleted)=>deleted?'<span class="muted">Удалённый пользователь</span>':link('/profile/'+encodeURIComponent(name),name);
const subject=id=>subjects.find(x=>x.id==id), topic=id=>topics.find(x=>x.id==id);
const empty=(title='Здесь пока нет материалов',body='Создайте первую публикацию или измените фильтры.',action='/new',label='Создать публикацию')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(body)}</p>${action?link(action,label):''}</div>`;
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function api(path,options={}){
 const headers={'X-CSRF-Token':csrf,...options.headers};let body=options.body;
 if(body&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body)}
 for(let attempt=0;attempt<2;attempt++){
  let response;try{response=await fetch(path,{...options,body,headers})}catch{throw Error('Нет соединения с сайтом. Проверьте, что сервер запущен, и повторите отправку. Введённые данные сохранены в форме.')}
  let result;try{result=await response.json()}catch{throw Error('Сервер вернул некорректный ответ. Повторите отправку позже.')}
  if(response.status===403&&result.code==='csrf_expired'&&attempt===0){
   const fresh=await api('/api/session');
   if((fresh.user?.username||null)!==(user?.username||null))throw Error('Аккаунт изменился в другой вкладке. Сохраните введённый текст и обновите страницу.');
   csrf=fresh.csrf;headers['X-CSRF-Token']=csrf;continue;
  }
  if(!response.ok)throw Error(result.error||'Не удалось выполнить действие');return result;
 }
}

function auth(){if(user)return true;authDialog();return false}
function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog').showModal()}
$('#close-dialog').onclick=()=>$('#dialog').close();
$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('hub_theme',document.body.classList.contains('dark')?'dark':'light')};
if(localStorage.getItem('hub_theme')==='dark')document.body.classList.add('dark');
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
function header(){ let notice=$('#mute-notice');if(!notice){notice=document.createElement('div');notice.id='mute-notice';notice.className='notice';$('#main').before(notice)}notice.hidden=!user?.muted;if(user?.muted)notice.textContent='Вы временно не можете писать и публиковать до '+new Date(user.muted_until).toLocaleString('ru-RU')+'. '+(user.mute_reason||'')+' Чтение и обращения к администрации доступны.'; $('#navAuth').innerHTML=user?`<details class="account"><summary>◉ ${esc(user.username)} ▾</summary><div class="account-menu">${link('/profile/'+encodeURIComponent(user.username),'Профиль')}${link('/my/posts','Мои публикации')}${link('/my/drafts','Черновики')}${link('/my/collections','Мои сборники')}${link('/my/saved','Сохранённое')}${link('/my/applications','Заявки в команду')}${link('/my/reports','Мои обращения')}${link('/settings','Настройки')}${user.role==='admin'?link('/admin?kind=deletion','Заявления на удаление'):''}${user.role!=='user'?link('/admin','Модерация'):''}<hr><button class="secondary" id="logout">Выйти</button></div></details>`:'<button id="login">Войти / Регистрация</button>';if($('#login'))$('#login').onclick=()=>authDialog();if($('#logout'))$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});location.href='/'};document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='/'?location.pathname==='/':location.pathname.startsWith(a.dataset.nav)))}
function authDialog(register=false){const previous=$('#auth-form'),values=previous?Object.fromEntries(new FormData(previous)):{};showDialog(register?'Создать аккаунт':'Войти в ResearchHub',`<p class="muted">${register?'Публикуйте материалы, собирайте подборки и участвуйте в обсуждениях.':'Рады видеть вас снова.'}</p><form id="auth-form"><label>Имя пользователя<input name="username" required minlength="3" maxlength="32" autocomplete="username"><small>3–32 буквы, цифры, дефис или подчёркивание. Без пробелов.</small></label><label>Пароль<input name="password" type="password" required minlength="${register?8:1}" maxlength="128" autocomplete="${register?'new-password':'current-password'}"></label><p class="error" role="alert"></p><button>${register?'Зарегистрироваться':'Войти'}</button></form><p class="muted"><small>Восстановление пароля по почте в локальной версии не настроено.</small></p><button id="switch-auth" class="secondary">${register?'Уже есть аккаунт':'Создать аккаунт'}</button>`);$('#auth-form [name=username]').value=values.username||'';$('#auth-form [name=password]').value=values.password||'';$('#switch-auth').onclick=()=>authDialog(!register);bindForm('#auth-form',async f=>{await api(register?'/api/register':'/api/login',{method:'POST',body:Object.fromEntries(new FormData(f))});location.reload()})}
function bindForm(selector,fn){const f=$(selector);if(!f)return;f.onsubmit=async e=>{e.preventDefault();const buttons=f.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);const error=f.querySelector('.error');if(error)error.textContent='';try{await fn(f,e)}catch(e){if(error)error.textContent=e.message;else toast(e.message)}finally{buttons.forEach(b=>b.disabled=false)}}}
function options(items,selected,blank){return (blank!==undefined?`<option value="">${esc(blank)}</option>`:'')+items.map(x=>`<option value="${x.id}" ${x.id==selected?'selected':''}>${esc(x.name)}</option>`).join('')}
function breadcrumb(p){return `<div class="crumbs">${link('/','Главная')} <span>›</span> ${link('/subjects/'+p.subject_id,p.subject_name||subject(p.subject_id)?.name)} <span>›</span> ${link('/topics/'+p.topic_id,p.topic_name||topic(p.topic_id)?.name)}${p.section?` <span>›</span> <span>${esc(p.section)}</span>`:''}${p.title?` <span>›</span> <span>${esc(p.title)}</span>`:''}</div>`}
function imageUrl(v){return typeof v==='string'&&(v.startsWith('/uploads/')||v.startsWith('https://')||/^data:image\/(png|jpeg|webp);base64,/.test(v))?esc(v):''}
function cards(items){return items.length?`<div class="cards">${items.map(p=>`<article class="card">${imageUrl(p.image)?`<a href="/post/${p.id}"><img class="cover" src="${imageUrl(p.image)}" alt="${esc(p.title)}" loading="lazy"></a>`:''}<span class="badge">${esc(kinds[p.kind])}${p.publication_status==='draft'?' · Черновик':''}</span><h3>${link('/post/'+p.id,p.title)}</h3><p>${esc((p.abstract||p.content||'Фотография').slice(0,170))}${(p.abstract||p.content||'').length>170?'…':''}</p><p>${link('/subjects/'+p.subject_id,p.subject_name)} <span> / </span>${link('/topics/'+p.topic_id,p.topic_name)}${p.section?' / '+esc(p.section):''}</p><div class="meta">${authorLink(p.author,p.author_deleted)} · ${date(p.created_at)}<div class="card-footer"><span>${p.comment_count} комментариев</span><button class="secondary" data-save="${p.id}">${p.saved?'Сохранено ✓':'Сохранить'}</button></div></div></article>`).join('')}</div>`:empty()}
function bindSaves(){document.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{if(!auth())return;b.disabled=true;try{await api('/api/bookmarks/toggle',{method:'POST',body:{post_id:+b.dataset.save}});b.textContent=b.textContent.includes('✓')?'Сохранить':'Сохранено ✓'}catch(e){toast(e.message)}finally{b.disabled=false}})}
async function home(){const p=await api('/api/posts');$('#main').innerHTML=`<section class="intro"><div><p class="eyebrow">Пространство для знаний</p><h1>Исследуйте. Делитесь.<br>Находите решения.</h1><p>Публикуйте работы, фотографии, задачи и идеи. Выбирайте предмет и тему, обсуждайте материалы и собирайте полезное в сборники.</p><a class="button" href="/new">＋ Создать публикацию</a></div><div class="intro-side"><h3>Что хотите изучить?</h3><form class="searchbar" action="/publications"><input aria-label="Поиск материалов" name="q" placeholder="Название, вопрос или ключевое слово"><button>Найти</button></form><p class="meta">Например: квантовая физика или геометрия</p></div></section><div class="section-head"><h2>Начните с предмета</h2>${link('/subjects','Все предметы →')}</div><div class="chips">${subjects.slice(0,7).map(s=>link('/subjects/'+s.id,s.name).replace('<a ','<a class="chip" ')).join('')}</div><div class="layout"><section><div class="section-head"><h2>Свежие материалы</h2>${link('/publications','Вся лента →')}</div>${cards(p.items.slice(0,6))}</section><aside class="panel side-panel"><p class="eyebrow">Ваша библиотека</p><h3>Собирайте важное</h3><p class="muted">Объединяйте публикации в сборники и задавайте свой порядок изучения.</p>${link('/collections','Открыть сборники →')}<hr>${user?`<h3>Мои материалы</h3>${link('/my/posts','Публикации')}${link('/my/drafts','Продолжить черновик')}${link('/my/saved','Сохранённое')}`:`<h3>Каждый вклад важен</h3><p class="muted">Уровень отражает активность в сообществе. Публикуйте и помогайте другим учиться.</p>`}</aside></div>`;bindSaves()}
function subjectPage(){ $('#main').innerHTML=`<p class="eyebrow">Каталог знаний</p><h1>Предметы и темы</h1><p class="muted">Сначала выберите направление, затем — тему. В каждой теме доступны все типы материалов.</p><div class="subject-grid">${subjects.map((s,i)=>`<a class="card subject-card" href="/subjects/${s.id}"><span class="subject-number">${String(i+1).padStart(2,'0')} / ПРЕДМЕТ</span><h3>${esc(s.name)}</h3><p>${esc(topics.filter(t=>t.subject_id===s.id&&t.name!=='Без темы').map(t=>t.name).join(' · '))}</p><span>Открыть направление →</span></a>`).join('')}</div>`}
async function listing({sid,tid,scope,title}={}){let params=new URLSearchParams(location.search);if(sid)params.set('subject_id',sid);if(tid){let t=topic(tid);if(!t)throw Error('Тема не найдена');params.set('topic_id',tid);params.set('subject_id',t.subject_id)}if(scope)params.set('scope',scope);const p=await api('/api/posts?'+params);const s=subject(params.get('subject_id')),t=topic(params.get('topic_id'));if(sid&&!s)throw Error('Предмет не найден');let collectionHtml='';if(t){const c=await api('/api/collections');const relevant=c.items.filter(c=>c.subject_id===s.id);collectionHtml=`<div class="section-head"><h2>Сборники по предмету</h2></div>${collectionCards(relevant)}`}
 $('#main').innerHTML=`${s?`<div class="crumbs">${link('/','Главная')} › ${link('/subjects','Предметы')}${t?' › '+link('/subjects/'+s.id,s.name):''}</div>`:''}<div class="section-head"><div><p class="eyebrow">${scope?'Личное пространство':'Библиотека сообщества'}</p><h1>${esc(title||t?.name||s?.name||'Публикации')}</h1></div><a class="button" href="/new${s?'?subject_id='+s.id+(t?'&topic_id='+t.id:''):''}">Создать публикацию</a></div>${s?`<p class="muted">${esc(t?.description||s.description)}</p>`:''}${s&&!t?`<div class="chips">${topics.filter(x=>x.subject_id===s.id).map(x=>`<a class="chip" href="/topics/${x.id}">${esc(x.name)}</a>`).join('')}</div>`:''}<form class="filters" id="filters"><label>Поиск<input name="q" value="${esc(params.get('q')||'')}" placeholder="По заголовку и содержанию"></label><label>Предмет<select name="subject_id">${options(subjects,s?.id,'Все предметы')}</select></label><label>Тема<select name="topic_id">${options(topics.filter(x=>x.subject_id===s?.id),t?.id,'Все темы')}</select></label><label>Тип<select name="kind"><option value="">Все типы</option>${Object.entries(kinds).map(([v,n])=>`<option value="${v}" ${params.get('kind')===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="filter-bottom"><label>Сортировка<select name="sort"><option value="new">Сначала новые</option><option value="old" ${params.get('sort')==='old'?'selected':''}>Сначала старые</option><option value="discussed" ${params.get('sort')==='discussed'?'selected':''}>По обсуждаемости</option></select></label><button>Применить</button>${link(scope?location.pathname:'/publications','Сбросить фильтры')}<span class="muted">Найдено: ${p.total}</span></div></form>${cards(p.items).replace('href="/new"','href="/new'+(s?'?subject_id='+s.id+(t?'&amp;topic_id='+t.id:''):'')+'"')}${collectionHtml}`;
 $('#filters [name=subject_id]').onchange=e=>{$('#filters [name=topic_id]').innerHTML=options(topics.filter(t=>t.subject_id==e.target.value),null,'Все темы')};$('#filters').onsubmit=e=>{e.preventDefault();const q=new URLSearchParams();for(const [k,v]of new FormData(e.target))if(v)q.set(k,v);location.href=(scope?location.pathname:'/publications')+'?'+q};bindSaves()}
function typeFields(){let kind=$('[name=kind]').value;document.querySelectorAll('[data-types]').forEach(x=>x.hidden=!x.dataset.types.split(',').includes(kind));$('#content-label').textContent={work:'Содержание',photo:'Подпись и описание',task:'Условие задачи',idea:'Описание идеи'}[kind]}
async function editor(pid){if(!user){$('#main').innerHTML=empty('Войдите, чтобы создать публикацию','Ваши материалы и черновики будут сохранены в аккаунте.',null);authDialog();return}const p=pid?(await api('/api/posts/'+pid)).post:{};if(pid&&p.author!==user.username&&user.role!=='admin')throw Error('Вы не можете редактировать чужую публикацию');const query=new URLSearchParams(location.search),sid=p.subject_id||query.get('subject_id')||subjects[0].id,tid=p.topic_id||query.get('topic_id');let token=crypto.randomUUID();
 $('#main').innerHTML=`<div class="editor"><div class="crumbs">${link('/','Главная')} › ${pid?'Редактирование':'Новая публикация'}</div><h1>${pid?'Редактировать публикацию':'Поделитесь своим материалом'}</h1><p class="muted">Выберите тип, предмет и тему. Черновик виден только вам.</p>${pid&&p.author!==user.username?`<p class="notice">Вы редактируете публикацию ${esc(p.author)}. Авторство сохраняется, изменение записывается в журнал администратора.</p>`:''}<form id="editor" class="panel"><div class="two"><label>Тип материала<select name="kind">${Object.entries(kinds).map(([v,n])=>`<option value="${v}" ${p.kind===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Заголовок<input name="title" required maxlength="180" value="${esc(p.title||'')}" placeholder="О чём ваш материал?"></label></div><div class="two"><label>Предмет<select name="subject_id">${options(subjects,sid)}</select></label><label>Тема<select name="topic_id">${options(topics.filter(t=>t.subject_id==sid),tid)}</select></label></div><label>Раздел внутри темы (необязательно)<input name="section" maxlength="120" value="${esc(p.section||'')}" placeholder="Например: Треугольники"><small>Короткая подтема. Условие вопроса напишите ниже, в содержании.</small></label><label><span id="content-label">Содержание</span><textarea name="content" rows="9" maxlength="100000">${esc(p.content||'')}</textarea><small>Поддерживаются Markdown и формулы: $x^2$ или $$E=mc^2$$. Небезопасный HTML удаляется.</small></label><div data-types="work"><label>Краткое описание<textarea name="abstract" rows="2">${esc(p.abstract||'')}</textarea></label><details><summary>Данные исследовательской работы</summary>${['methodology','coauthors','book_author','volume','book_reference'].map((k,i)=>`<label>${['Методология','Соавторы','Автор книги / источника','Том','Ссылка на книгу'][i]}<input name="${k}" value="${esc(p[k]||'')}"></label>`).join('')}</details><label>Источники<textarea name="references_list">${esc(p.references_list||'')}</textarea></label></div><div data-types="task"><div class="two"><label>Сложность<input name="difficulty" value="${esc(p.difficulty||'')}" placeholder="Например, школьная"></label><label>Олимпиада<input name="olympiad_name" value="${esc(p.olympiad_name||'')}"></label></div><label>Подсказка<textarea name="hint">${esc(p.hint||'')}</textarea></label><label>Ответ или решение<textarea name="solution">${esc(p.solution||'')}</textarea><small>Читатель сможет раскрыть решение отдельно.</small></label><label>Файл решения<input name="solution_file" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg,.webp"></label></div><div data-types="idea"><label>Цель<textarea name="goal">${esc(p.goal||'')}</textarea></label><label>Вопросы для обсуждения<textarea name="questions">${esc(p.questions||'')}</textarea></label><label>Кого ищете в команду<input name="roles_needed" value="${esc(p.roles_needed||'')}" placeholder="Необязательно, например: дизайнер"></label></div><label>Теги<input name="tags" value="${esc(p.tags||'')}" placeholder="Через запятую"></label><div class="two"><label>Фото или обложка<input name="cover" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG, WEBP · до 10 МБ, 20 Мп. Для фото обязательно.</small>${p.image?'<small>Текущее изображение сохранится, если не выбрать новое.</small>':''}</label><label>Вложение<input name="file" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg,.webp"><small>PDF, TXT, PNG, JPG, WEBP · до 10 МБ.</small>${p.filename?`<small>Сохранён файл: ${esc(p.filename)}</small>`:''}</label></div><p class="error" role="alert"></p><div class="actions"><button name="action" value="published">${p.publication_status==='published'?'Сохранить изменения':'Опубликовать'}</button>${p.publication_status!=='published'?'<button name="action" value="draft" class="secondary">Сохранить черновик</button>':''}<button type="button" id="preview" class="secondary">Предпросмотр</button><a class="button secondary" href="${pid?'/post/'+pid:'/'}">Отмена</a></div></form></div>`;
 typeFields();$('[name=kind]').onchange=typeFields;$('[name=subject_id]').onchange=e=>$('[name=topic_id]').innerHTML=options(topics.filter(t=>t.subject_id==e.target.value));$('#editor').oninput=()=>dirty=true;
 $('#preview').onclick=async()=>{const f=new FormData($('#editor'));showDialog('Предпросмотр',`<span class="badge">${kinds[f.get('kind')]}</span><h2>${esc(f.get('title')||'Без заголовка')}</h2><p class="meta">${esc(subject(f.get('subject_id'))?.name)} / ${esc(topic(f.get('topic_id'))?.name)}${f.get('section')?' / '+esc(f.get('section')):''}</p><div class="prose rich">${rich(f.get('content'))}</div>${f.get('hint')?`<details><summary>Подсказка</summary><div class="prose rich">${rich(f.get('hint'))}</div></details>`:''}${f.get('solution')?`<details><summary>Решение</summary><div class="prose rich">${rich(f.get('solution'))}</div></details>`:''}`);const file=f.get('cover');if(file&&file.size&&/^image\/(png|jpeg|webp)$/.test(file.type)){const reader=new FileReader();reader.onload=()=>{const img=document.createElement('img');img.src=reader.result;img.alt='Предпросмотр фотографии';img.className='full-image';$('#dialog-body').append(img)};reader.readAsDataURL(file)}};
 bindForm('#editor',async(f,e)=>{const body=new FormData(f);body.set('publication_status',e.submitter?.value||'published');const result=await api('/api/posts'+(pid?'/'+pid:''),{method:pid?'PUT':'POST',body,headers:{'Idempotency-Key':token}});dirty=false;location.href='/post/'+result.id})}
function attachment(path,name){if(!name)return '';const url=path?.startsWith('/uploads/')?path:'/uploads/'+encodeURIComponent(name);return `<a class="button secondary" href="${esc(url)}" target="_blank" rel="noopener">↓ ${esc(name)}</a>`}
async function postPage(pid){const d=await api('/api/posts/'+pid),p=d.post,mine=user?.username===p.author,canManage=mine||user?.role==='admin';
 $('#main').innerHTML=`<div class="article">${breadcrumb(p)}<article class="panel"><span class="badge">${kinds[p.kind]}${p.publication_status==='draft'?' · Черновик':''}</span><h1>${esc(p.title)}</h1><p class="meta">${authorLink(p.author,p.author_deleted)} · ${date(p.created_at)}${p.updated_at&&p.updated_at!==p.created_at?' · Изменено '+date(p.updated_at):''}</p>${p.publication_status==='draft'?'<p class="notice">Это ваш черновик. Он недоступен другим пользователям.</p>':''}${p.abstract?`<p class="notice">${esc(p.abstract)}</p>`:''}${imageUrl(p.image)?`<a href="${imageUrl(p.image)}" target="_blank" rel="noopener"><img class="full-image" src="${imageUrl(p.image)}" alt="${esc(p.title)}"></a>`:''}<div class="prose rich">${rich(p.content)}</div>${p.difficulty?`<p class="meta">Сложность: ${esc(p.difficulty)}</p>`:''}${['methodology','coauthors','book_author','volume','book_reference','references_list','goal','questions'].filter(k=>p[k]).map(k=>`<h3>${({methodology:'Методология',coauthors:'Соавторы',book_author:'Автор источника',volume:'Том',book_reference:'Книга',references_list:'Источники',goal:'Цель',questions:'Вопросы для обсуждения'})[k]}</h3><div class="prose rich">${rich(p[k])}</div>`).join('')}${p.hint?`<details><summary>Показать подсказку</summary><div class="prose rich">${rich(p.hint)}</div></details>`:''}${p.solution||p.solution_filename?`<details><summary>Показать ответ / решение</summary><div class="prose rich">${rich(p.solution)}</div>${attachment(p.solution_filepath,p.solution_filename)}</details>`:''}<div class="actions">${attachment(p.filepath,p.filename)}</div>${p.tags?`<p class="meta">Теги: ${esc(p.tags)}</p>`:''}${p.roles_needed?`<div class="notice">В команду нужны: ${esc(p.roles_needed)} <button id="apply" class="secondary">Откликнуться</button></div>`:''}<div class="actions"><button class="secondary" data-save="${pid}">${p.saved?'Сохранено ✓':'Сохранить'}</button>${p.publication_status==='published'?`<button id="add-collection" class="secondary">Добавить в сборник</button><button id="helpful" class="secondary">Полезно · ${p.helpful}</button>`:''}${canManage?`<a class="button" href="/edit/${pid}">${p.publication_status==='draft'?'Продолжить черновик':'Редактировать'}</a><button id="delete-post" class="danger">Удалить</button>`:`<button id="report" class="secondary">Пожаловаться</button>`}${p.publication_status==='published'&&user?.role!=='admin'?'<button id="request-deletion" class="secondary">Заявление на удаление</button>':''}</div></article>${p.publication_status==='published'?`<section class="panel" id="comments"><h2>Обсуждение · ${d.comments.filter(c=>!c.deleted).length}</h2>${user?`<form id="comment-form"><label>Ваш комментарий<textarea name="text" maxlength="5000" placeholder="Задайте вопрос или поделитесь решением"></textarea></label>${commentImageField()}<p class="error" role="alert"></p><button>Добавить комментарий</button></form>`:`<p class="notice">Войдите в аккаунт, чтобы оставить комментарий. <button id="comment-login" class="secondary">Войти</button></p>`}${d.comments.map(c=>`<div id="comment-${c.id}" class="comment ${c.parent_id?'reply':''}"><span class="meta">${authorLink(c.author,c.author_deleted)} · ${date(c.created_at)}${c.updated_at?' · изменено':''}${c.is_accepted?' · ✓ Принятое решение':''}</span>${c.parent_id?`<blockquote>Ответ ${esc(d.comments.find(x=>x.id===c.parent_id)?.author||'участнику')}</blockquote>`:''}<p class="prose">${c.deleted?'Комментарий удалён':esc(c.text)}</p>${!c.deleted?attachment(c.filepath,c.filename):''}${!c.deleted&&imageUrl(c.image)?`<img class="full-image" src="${imageUrl(c.image)}" alt="Изображение к комментарию">`:''}${!c.deleted?`<div class="actions"><button class="secondary" data-reply="${c.id}">Ответить</button>${user?.username===c.author?`<button class="secondary" data-edit-comment="${c.id}">Редактировать</button>`:''}${user?.username===c.author||user?.role==='admin'?`<button class="danger" data-delete-comment="${c.id}">Удалить</button>`:''}<button class="secondary" data-report-comment="${c.id}">Пожаловаться</button>${mine&&p.kind==='task'?`<button class="secondary" data-accept="${c.id}">Принять решение</button>`:''}</div>`:''}</div>`).join('')||'<p class="muted">Пока нет комментариев. Начните обсуждение.</p>'}</section>`:''}</div>`;
 bindSaves();if($('#comment-login'))$('#comment-login').onclick=()=>authDialog();let commentToken=crypto.randomUUID();bindForm('#comment-form',async f=>{await api(`/api/posts/${pid}/comments`,{method:'POST',body:new FormData(f),headers:{'Idempotency-Key':commentToken}});await postPage(pid);$('#comments').scrollIntoView()});
 bindImagePreview($('#comment-form'));document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>commentDialog(pid,+b.dataset.reply));document.querySelectorAll('[data-report-comment]').forEach(b=>b.onclick=()=>targetReport('comment',+b.dataset.reportComment));

 document.querySelectorAll('[data-edit-comment]').forEach(b=>b.onclick=()=>textDialog('Редактировать комментарий','Текст',d.comments.find(c=>c.id==b.dataset.editComment).text,async text=>{await api('/api/comments/'+b.dataset.editComment,{method:'PUT',body:{text}});await postPage(pid)}));
 document.querySelectorAll('[data-delete-comment]').forEach(b=>b.onclick=()=>confirmDialog('Удалить комментарий?','Ответы других участников сохранятся.',async()=>{await api('/api/comments/'+b.dataset.deleteComment,{method:'DELETE'});await postPage(pid)}));
 document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>safeAction(b,async()=>{await api('/api/comments/'+b.dataset.accept+'/accept',{method:'POST'});await postPage(pid)}));
 if($('#delete-post'))$('#delete-post').onclick=()=>confirmDialog('Удалить публикацию?','Материал станет недоступен. Связанное начисление XP будет отменено.',async()=>{await api(`/api/posts/${pid}/delete`,{method:'DELETE'});location.href=mine?'/my/posts':'/publications'});
 if($('#helpful'))$('#helpful').onclick=()=>{if(auth())safeAction($('#helpful'),async()=>{await api(`/api/posts/${pid}/like`,{method:'POST'});await postPage(pid);toast('Отметка полезности сохранена')})};
 if($('#add-collection'))$('#add-collection').onclick=()=>addCollection(pid);
 if($('#request-deletion'))$('#request-deletion').onclick=()=>{if(auth())deletionRequest(pid)};
 if($('#report'))$('#report').onclick=()=>{if(auth())textDialog('Пожаловаться на материал','Причина жалобы','',async reason=>{await api('/api/reports',{method:'POST',body:{post_id:pid,reason}});toast('Жалоба передана модератору')})};
 if($('#apply'))$('#apply').onclick=()=>{if(auth())textDialog('Откликнуться на проект','Расскажите о себе и своей роли','',async message=>{await api(`/api/posts/${pid}/apply`,{method:'POST',body:{role_applied:p.roles_needed,message}});toast('Заявка отправлена автору')})};
}
async function safeAction(b,fn){b.disabled=true;try{await fn()}catch(e){toast(e.message)}finally{b.disabled=false}}
function textDialog(title,label,value,fn){const token=crypto.randomUUID();showDialog(title,`<form id="text-form"><label>${esc(label)}<textarea name="text" required maxlength="5000">${esc(value)}</textarea></label><p class="error" role="alert"></p><button>Сохранить</button></form>`);bindForm('#text-form',async f=>{await fn(new FormData(f).get('text'),token);$('#dialog').close()})}
function confirmDialog(title,body,fn){showDialog(title,`<p>${esc(body)}</p><form id="confirm-form"><p class="error" role="alert"></p><div class="actions"><button class="danger">Удалить</button><button type="button" id="cancel" class="secondary">Отмена</button></div></form>`);$('#cancel').onclick=()=>$('#dialog').close();bindForm('#confirm-form',async()=>{await fn();$('#dialog').close()})}
function collectionCards(items){return items.length?`<div class="cards">${items.map(c=>`<article class="card"><span class="badge">Сборник · ${c.count} материалов</span><h3>${link('/collections/'+c.id,c.title)}</h3><p>${esc(c.description.slice(0,180))}</p><div class="meta">${authorLink(c.author,c.author_deleted)} · ${esc(subject(c.subject_id)?.name)}</div></article>`).join('')}</div>`:empty('Сборников пока нет','Создайте подборку и добавьте в неё публикации.',null)}
async function collectionsPage(mine=false){const d=await api('/api/collections'+(mine?'?mine=1':''));$('#main').innerHTML=`<div class="section-head"><div><p class="eyebrow">Знания по порядку</p><h1>${mine?'Мои сборники':'Сборники'}</h1></div><button id="new-collection">Создать сборник</button></div><p class="muted">Подборки работ, задач, фотографий и идей. Сохраняйте материалы и выстраивайте свой маршрут изучения.</p>${collectionCards(d.items)}`;$('#new-collection').onclick=()=>{if(auth())collectionForm()}}
function collectionForm(c){showDialog(c?'Редактировать сборник':'Новый сборник',`<form id="collection-form"><label>Название<input name="title" required maxlength="180" value="${esc(c?.title||'')}"></label><label>Описание<textarea name="description" maxlength="10000">${esc(c?.description||'')}</textarea></label>${!c?`<label>Предмет<select name="subject_id">${options(subjects)}</select></label>`:''}<p class="error" role="alert"></p><button>Сохранить сборник</button></form>`);const token=crypto.randomUUID();bindForm('#collection-form',async f=>{const r=await api('/api/collections'+(c?'/'+c.id:''),{method:c?'PUT':'POST',body:Object.fromEntries(new FormData(f)),headers:{'Idempotency-Key':token}});location.href='/collections/'+(c?.id||r.id)})}
async function addCollection(pid){if(!auth())return;try{const d=await api('/api/collections?mine=1');showDialog('Добавить в свой сборник',d.items.length?`<form id="add-form"><label>Сборник<select name="id">${options(d.items.map(c=>({id:c.id,name:c.title})))}</select></label><p class="error" role="alert"></p><button>Добавить материал</button></form>`:`<p>Сначала создайте свой сборник.</p>${link('/my/collections','Перейти к моим сборникам →')}`);bindForm('#add-form',async f=>{const id=new FormData(f).get('id'),c=await api('/api/collections/'+id),ids=c.items.map(x=>x.post_id);if(!ids.includes(pid))ids.push(pid);await api('/api/collections/'+id+'/items',{method:'PUT',body:{post_ids:ids}});$('#dialog').close();toast('Материал добавлен в сборник')})}catch(e){toast(e.message)}}
async function collectionPage(cid){const d=await api('/api/collections/'+cid),c=d.collection,mine=user?.username===c.author;$('#main').innerHTML=`<div class="article"><div class="crumbs">${link('/','Главная')} › ${link('/collections','Сборники')}</div><section class="panel"><span class="badge">Сборник</span><h1>${esc(c.title)}</h1><p class="meta">${authorLink(c.author,c.author_deleted)} · ${date(c.created_at)} · ${esc(subject(c.subject_id)?.name)}</p><p class="prose">${esc(c.description)}</p>${mine?'<div class="actions"><button id="edit-collection" class="secondary">Редактировать сборник</button><a class="button" href="/publications">Найти материалы</a><button id="delete-collection" class="danger">Удалить сборник</button></div><p class="meta">Откройте публикацию и нажмите «Добавить в сборник». Порядок меняется стрелками.</p>':''}${d.items.map((i,n)=>`<div class="collection-item"><div><span class="eyebrow">${String(n+1).padStart(2,'0')}</span><h3>${i.post?link('/post/'+i.post_id,i.post.title):'Материал недоступен'}</h3><span class="meta">${i.post?esc(kinds[i.post.kind]+' · '+i.post.author):'Публикация удалена или скрыта автором.'}</span></div>${mine?`<div class="row"><button class="secondary" data-move="${n}" data-step="-1" ${n===0?'disabled':''} aria-label="Переместить вверх">↑</button><button class="secondary" data-move="${n}" data-step="1" ${n===d.items.length-1?'disabled':''} aria-label="Переместить вниз">↓</button><button class="secondary" data-remove="${i.post_id}">Убрать</button></div>`:''}</div>`).join('')||empty('Добавьте первый материал','Публикации можно добавлять в сборник с их страницы.','/publications','Найти материал')}</section></div>`;
 const update=async ids=>{await api(`/api/collections/${cid}/items`,{method:'PUT',body:{post_ids:ids}});await collectionPage(cid)};
 document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>safeAction(b,async()=>{const ids=d.items.map(x=>x.post_id),n=+b.dataset.move,k=n+(+b.dataset.step);[ids[n],ids[k]]=[ids[k],ids[n]];await update(ids)}));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>safeAction(b,async()=>{await update(d.items.map(x=>x.post_id).filter(id=>id!=b.dataset.remove));toast('Убрано из сборника. Публикация сохранена.')}));if(mine){$('#edit-collection').onclick=()=>collectionForm(c);$('#delete-collection').onclick=()=>confirmDialog('Удалить сборник?','Сами публикации сохранятся.',async()=>{await api('/api/collections/'+cid,{method:'DELETE'});location.href='/my/collections'})}}
async function profilePage(name){const p=await api('/api/profile/'+encodeURIComponent(name));const [posts,c]=await Promise.all([api('/api/posts?author='+encodeURIComponent(name)),api('/api/collections?author='+encodeURIComponent(name))]);$('#main').innerHTML=`<div class="layout"><section><div class="panel"><div class="profile-head">${imageUrl(p.avatar)?`<img class="avatar" src="${imageUrl(p.avatar)}" alt="Аватар ${esc(name)}">`:`<span class="avatar">${esc((p.display_name||name).slice(0,1).toUpperCase())}</span>`}<div><h1>${esc(p.display_name||name)}</h1><span class="muted">@${esc(name)} · ${roles[p.role]}<br>Регистрация: ${date(p.created_at)}</span><p><span class="badge">${ageBadge(p.days_on_site)}</span></p>${name!==user?.username?'<button id="report-user" class="secondary">Пожаловаться на пользователя</button>':''}</div></div><p class="prose">${esc(p.bio||'Пользователь ещё не добавил описание.')}</p>${p.school?`<p class="meta">${esc(p.school)}</p>`:''}${p.achievements?`<p class="meta">${esc(p.achievements)}</p>`:''}<div class="stats"><div><strong>${p.posts_count}</strong>публикаций</div><div><strong>${p.collections_count}</strong>сборников</div><div><strong>${p.comments_count}</strong>комментариев</div></div>${name===user?.username?link('/settings','Редактировать профиль →'):''}</div><div class="section-head"><h2>Публикации</h2></div>${cards(posts.items)}<div class="section-head"><h2>Сборники</h2></div>${collectionCards(c.items)}</section><aside><div class="panel"><p class="eyebrow">Опыт сообщества</p><h2>${esc(p.level_title)}</h2><h3>${p.xp} XP</h3><progress max="${p.next_level?p.next_level-p.level_start:1}" value="${p.next_level?p.xp-p.level_start:1}" aria-label="Прогресс до следующего уровня"></progress><p class="meta">${p.next_level?'До следующего уровня: '+(p.next_level-p.xp)+' XP':'Достигнут высший уровень'}</p><p class="muted">Уровень отражает активность, а не профессиональную квалификацию. Он не даёт прав модератора или администратора.</p><details><summary>Как начисляется опыт</summary><p class="meta">Настройка имени и описания профиля: ${state.config.xp.profile} XP один раз. Публикация: ${state.config.xp.publication} XP (до ${state.config.daily_caps.publication} за сутки UTC). Сборник с описанием и двумя публикациями: ${state.config.xp.collection} XP (до ${state.config.daily_caps.collection} за сутки). Полезность от другого пользователя: ${state.config.xp.helpful} XP (до ${state.config.daily_caps.helpful} за сутки). За комментарии и входы XP не начисляется.</p><p class="meta">Удаление материала отменяет его XP. Повторное сохранение и восстановление события не дают повторного начисления.</p></details></div></aside></div>${p.events?`<div class="section-head"><h2>Моя история опыта</h2></div><div class="panel"><table class="history"><thead><tr><th>Дата</th><th>Событие</th><th>XP</th></tr></thead><tbody>${p.events.map(e=>`<tr><td>${date(e.created_at)}</td><td>${({profile:'Настройка профиля',publication:'Публикация',collection:'Сборник',helpful:'Полезность'})[e.kind]}${e.reversed_at?' · отменено':''}</td><td>${e.reversed_at?'0 (было '+e.amount+')':'+'+e.amount}</td></tr>`).join('')||'<tr><td colspan="3">Начислений пока нет</td></tr>'}</tbody></table></div>`:''}`;bindSaves();if($('#report-user'))$('#report-user').onclick=()=>targetReport('user',name)}
async function settings(){if(!user){authDialog();$('#main').innerHTML=empty('Настройки доступны после входа','Войдите через блок аккаунта в шапке.',null);return}const p=await api('/api/profile/'+encodeURIComponent(user.username));$('#main').innerHTML=`<div class="editor"><h1>Настройки профиля</h1><p class="muted">Имя, описание и аватар будут видны другим пользователям.</p><form id="settings" class="panel"><label>Отображаемое имя<input name="display_name" required maxlength="100" value="${esc(p.display_name||p.username)}"></label><label>О себе<textarea name="bio" maxlength="2000">${esc(p.bio||'')}</textarea></label><label>Школа / организация<input name="school" value="${esc(p.school||'')}"></label><label>Достижения<textarea name="achievements">${esc(p.achievements||'')}</textarea></label><label>Аватар<input type="file" name="avatar" accept="image/png,image/jpeg,image/webp"><small>До 10 МБ, 20 Мп.</small></label><p class="error" role="alert"></p><button>Сохранить профиль</button></form><h2>Изменить пароль</h2><form id="password-form" class="panel"><label>Текущий пароль<input type="password" name="current_password" required autocomplete="current-password"></label><label>Новый пароль<input type="password" name="new_password" required minlength="8" maxlength="128" autocomplete="new-password"></label><p class="error" role="alert"></p><button>Изменить пароль</button></form></div>`;bindForm('#settings',async f=>{await api('/api/profile/update',{method:'POST',body:new FormData(f)});toast('Профиль сохранён')});bindForm('#password-form',async f=>{await api('/api/password',{method:'POST',body:Object.fromEntries(new FormData(f))});f.reset();toast('Пароль изменён')})}
async function applications(){const d=await api('/api/applications');$('#main').innerHTML=`<h1>Заявки в мои проекты</h1>${d.items.map(a=>`<article class="panel"><h3>${link('/post/'+a.post_id,a.title)}</h3><p>${esc(a.applicant)} · ${esc(a.role_applied)}</p><p class="prose">${esc(a.message)}</p><p class="meta">${esc(a.status)}</p>${a.status==='pending'?`<div class="actions"><button data-application="${a.id}" data-status="accepted">Принять</button><button class="secondary" data-application="${a.id}" data-status="rejected">Отклонить</button></div>`:''}</article>`).join('')||empty('Заявок пока нет','В публикации типа «Идея» можно указать, кого вы ищете в команду.',null)}`;document.querySelectorAll('[data-application]').forEach(b=>b.onclick=()=>safeAction(b,async()=>{await api('/api/applications/'+b.dataset.application,{method:'PUT',body:{status:b.dataset.status}});await applications()}))}
function reportStatus(r){
 return r.status==='open'?'Ожидает рассмотрения':r.outcome==='deleted'?'Удалено':r.outcome==='muted'?'Пользователю назначен мут':r.outcome==='kept'?'Рассмотрено: сохранено':'Рассмотрено';
}
function reportCards(items,staffView=false){
 return items.map(r=>`<article class="panel report-card"><span class="badge">${r.kind==='deletion'?'Заявление на удаление':'Жалоба'} №${r.id}</span><h3>${r.deleted_at||r.outcome==='deleted'?esc(r.post_title):link(r.target_type==='user'?'/profile/'+encodeURIComponent(r.target_username):'/post/'+r.post_id+(r.target_type==='comment'?'#comment-'+r.comment_id:''),r.post_title||'Публикация №'+r.post_id)}</h3><p class="meta">${staffView?'От: '+esc(r.reporter)+' · ':''}${date(r.created_at)}</p>${r.target_excerpt?`<blockquote>${esc(r.target_excerpt)}</blockquote>`:''}<p class="prose">${esc(r.reason)}</p><p><strong>${reportStatus(r)}</strong></p>${r.resolution?`<p class="prose">${esc(r.resolution)}</p><p class="meta">${r.resolved_by?esc(r.resolved_by)+' · ':''}${date(r.resolved_at)}</p>`:''}${staffView&&r.status==='open'?`<button data-report="${r.id}">Рассмотреть</button>`:''}</article>`).join('')||empty('Обращений нет','Здесь появятся заявления и результаты их рассмотрения.',null);
}
function deletionRequest(pid){
 showDialog('Заявление на удаление публикации',`<p>Укажите, почему публикацию нужно удалить. Заявление получит администратор; материал останется доступен до принятия решения.</p><form id="deletion-form"><label>Причина<textarea name="reason" required maxlength="2000"></textarea></label><p class="error" role="alert"></p><button>Отправить заявление</button></form><p class="meta">Результат появится в разделе ${link('/my/reports','Мои обращения')}.</p>`);
 bindForm('#deletion-form',async f=>{const r=await api('/api/reports',{method:'POST',body:{post_id:pid,kind:'deletion',reason:new FormData(f).get('reason')}});$('#dialog').close();toast('Заявление №'+r.id+' отправлено администратору')});
}
async function myReports(){
 const d=await api('/api/my/reports');$('#main').innerHTML=`<div class="article"><h1>Мои обращения</h1><p class="muted">Заявления на удаление, жалобы и ответы администрации.</p>${reportCards(d.items)}</div>`;
}
function inbox(items){
 const selected=new URLSearchParams(location.search).get('kind');
 return `<section><h2>Обращения участников</h2><p class="muted">Заявлений на удаление в ожидании: ${items.filter(r=>r.kind==='deletion'&&r.status==='open').length}. Жалоб: ${items.filter(r=>r.kind==='complaint'&&r.status==='open').length}.</p><div class="two"><label>Тип обращения<select id="report-kind"><option value="">Все обращения</option>${user.role==='admin'?`<option value="deletion" ${selected==='deletion'?'selected':''}>Заявления на удаление</option>`:''}<option value="complaint">Жалобы</option></select></label><label>Статус<select id="report-status"><option value="open">Ожидают рассмотрения</option><option value="resolved">Рассмотренные</option><option value="">Все статусы</option></select></label></div><div id="report-list" aria-live="polite"></div></section>`;
}
function bindInbox(items){
 const render=()=>{
  const kind=$('#report-kind').value,status=$('#report-status').value;
  $('#report-list').innerHTML=reportCards(items.filter(r=>(!kind||r.kind===kind)&&(!status||r.status===status)),true);
  document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{
   const report=items.find(r=>r.id===+b.dataset.report);
   const isUser=report.target_type==='user',label=isUser?'аккаунт':report.target_type==='comment'?'комментарий / ответ':'публикацию';
   showDialog('Рассмотреть обращение №'+report.id,`<p>${esc(report.post_title)}</p><p class="prose">${esc(report.reason)}</p><form id="resolve"><label>Решение<select name="action"><option value="keep">Сохранить / отклонить жалобу</option>${isUser?'<option value="mute">Назначить мут</option>':''}<option value="delete">Удалить ${label}</option></select></label>${isUser?'<div id="mute-duration" hidden>'+durationField()+'</div>':''}<label>Ответ заявителю<textarea name="resolution" required maxlength="2000"></textarea></label><p class="notice">${isUser?'Удаление аккаунта отключит вход и скроет профиль. Опубликованные материалы сохранятся с пометкой «Удалённый пользователь».':report.target_type==='comment'?'Ответы на удалённый комментарий сохранятся.':'Удаление уберёт публикацию из доступа и отменит связанный XP.'} Действие записывается в журнал.</p><p class="error" role="alert"></p><button>Подтвердить решение</button></form>`);
   if(isUser)$('[name=action]').onchange=e=>$('#mute-duration').hidden=e.target.value!=='mute';
   bindForm('#resolve',async f=>{const d=Object.fromEntries(new FormData(f));if(d.action==='mute')d.minutes=+d.duration*+d.unit;await api('/api/reports/'+report.id,{method:'PUT',body:d});$('#dialog').close();await admin();toast('Решение сохранено. Ответ доступен заявителю.')});
  });
 };
 $('#report-kind').onchange=render;$('#report-status').onchange=render;render();
}


function ageBadge(n){if(n===null||n===undefined)return 'Дата регистрации неизвестна';const last=n%10,teen=n%100;return `${n} ${last===1&&teen!==11?'день':last>=2&&last<=4&&(teen<12||teen>14)?'дня':'дней'} на сайте`}
function commentImageField(){return '<label>Изображение (необязательно)<input type="file" name="comment_image" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG, WEBP · до 10 МБ, 20 Мп. Можно отправить изображение без текста.</small></label><img class="full-image comment-preview" alt="Предпросмотр изображения" hidden>'}
function bindImagePreview(form){if(!form)return;const input=form.querySelector('[name=comment_image]'),img=form.querySelector('.comment-preview');input.onchange=()=>{const file=input.files[0];img.hidden=true;if(file&&file.size<=10*1024*1024){const reader=new FileReader();reader.onload=()=>{img.src=reader.result;img.hidden=false};reader.readAsDataURL(file)}}}
function commentDialog(pid,parent){if(!auth())return;const token=crypto.randomUUID();showDialog('Ответить на комментарий',`<form id="reply-form"><label>Ваш ответ<textarea name="text" maxlength="5000"></textarea></label>${commentImageField()}<p class="error" role="alert"></p><button>Отправить ответ</button></form>`);bindImagePreview($('#reply-form'));bindForm('#reply-form',async f=>{const body=new FormData(f);body.set('parent_id',parent);await api('/api/posts/'+pid+'/comments',{method:'POST',body,headers:{'Idempotency-Key':token}});$('#dialog').close();await postPage(pid);$('#comments').scrollIntoView()})}
function targetReport(type,id){if(!auth())return;showDialog('Жалоба администратору',`<form id="target-report"><label>Причина жалобы<textarea name="reason" required maxlength="2000"></textarea></label><p class="meta">Ответ появится в разделе «Мои обращения».</p><p class="error" role="alert"></p><button>Отправить жалобу</button></form>`);bindForm('#target-report',async f=>{const body={target_type:type,reason:new FormData(f).get('reason')};body[type==='user'?'target_username':'comment_id']=id;await api('/api/reports',{method:'POST',body});$('#dialog').close();toast('Жалоба отправлена администратору')})}
function durationField(){return '<div class="two"><label>Длительность<input name="duration" type="number" min="1" max="5256000" step="1" value="1" required></label><label>Единица времени<select name="unit"><option value="1">Минуты</option><option value="60" selected>Часы</option><option value="1440">Дни</option></select></label></div><small>Максимум — 3650 дней.</small>'}
function bindUserModeration(){document.querySelectorAll('[data-mute]').forEach(b=>b.onclick=()=>{showDialog('Мут: '+b.dataset.mute,`<form id="mute-form">${durationField()}<label>Причина<textarea name="reason" maxlength="1000"></textarea></label><p class="notice">До истечения срока пользователь не сможет писать, публиковать и редактировать материалы.</p><p class="error" role="alert"></p><button>Назначить мут</button></form>`);bindForm('#mute-form',async f=>{const d=Object.fromEntries(new FormData(f));await api('/api/admin/users/'+encodeURIComponent(b.dataset.mute)+'/mute',{method:'PUT',body:{minutes:+d.duration*+d.unit,reason:d.reason}});$('#dialog').close();await admin()})});document.querySelectorAll('[data-unmute]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/users/'+encodeURIComponent(b.dataset.unmute)+'/mute',{method:'PUT',body:{minutes:0}});await admin()}catch(e){toast(e.message)}});document.querySelectorAll('[data-delete-user]').forEach(b=>b.onclick=()=>confirmDialog('Удалить аккаунт '+b.dataset.deleteUser+'?','Вход будет отключён, профиль скрыт. Опубликованные материалы и ответы сохранятся с пометкой «Удалённый пользователь».',async()=>{await api('/api/admin/users/'+encodeURIComponent(b.dataset.deleteUser),{method:'DELETE'});await admin()}))}

async function admin(){const reports=await api('/api/reports');let a=user.role==='admin'?await api('/api/admin'):null;$('#main').innerHTML=`<h1>Модерация</h1><p class="muted">Действия модерации записываются в журнал. Уровень XP не влияет на права.</p>${inbox(reports.items)}${a?`<h2>Пользователи и ограничения</h2><div class="panel">${a.users.map(u=>`<div class="user-admin"><form class="role-form row"><label>${esc(u.username)}<input type="hidden" name="username" value="${esc(u.username)}"><select name="role">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${u.role===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="secondary">Сохранить роль</button><p class="error" role="alert"></p></form>${u.role!=='admin'?`<div class="actions"><button class="secondary" data-mute="${esc(u.username)}">Назначить / изменить мут</button>${u.muted_until&&new Date(u.muted_until)>new Date()?`<button class="secondary" data-unmute="${esc(u.username)}">Снять мут</button><span class="meta">До ${esc(new Date(u.muted_until).toLocaleString('ru-RU'))} · ${esc(u.mute_reason)}</span>`:''}<button class="danger" data-delete-user="${esc(u.username)}">Удалить аккаунт</button></div>`:''}</div>`).join('')}</div><h2>Добавить предмет или тему</h2><form id="taxonomy" class="panel"><label>Родительский предмет<select name="subject_id">${options(subjects,null,'Новый предмет')}</select></label><label>Название<input name="name" required maxlength="100"></label><label>Описание<textarea name="description" required maxlength="2000"></textarea></label><p class="error" role="alert"></p><button>Добавить</button></form><h2>Журнал действий</h2><div class="panel">${a.audit.map(r=>`<p class="meta">${esc(r.created_at)} · ${esc(r.actor)} · ${esc(r.action)} · ${esc(r.entity)}</p>`).join('')||'<p>Записей пока нет.</p>'}</div>`:''}`;
 bindUserModeration();bindInbox(reports.items);document.querySelectorAll('.role-form').forEach((f,i)=>{f.id='role-'+i;bindForm('#'+f.id,async f=>{await api('/api/admin/role',{method:'PUT',body:Object.fromEntries(new FormData(f))});await admin();toast('Роль обновлена')})});bindForm('#taxonomy',async f=>{await api('/api/admin/taxonomy',{method:'POST',body:Object.fromEntries(new FormData(f))});location.reload()})}
async function route(){const path=decodeURI(location.pathname);if(path==='/')return home();if(path==='/subjects')return subjectPage();if(/^\/subjects\/\d+$/.test(path))return listing({sid:+path.split('/')[2]});if(/^\/topics\/\d+$/.test(path))return listing({tid:+path.split('/')[2]});if(path==='/publications')return listing();if(path==='/new')return editor();if(/^\/edit\/\d+$/.test(path))return editor(+path.split('/')[2]);if(/^\/post\/\d+$/.test(path))return postPage(+path.split('/')[2]);if(path==='/collections')return collectionsPage();if(/^\/collections\/\d+$/.test(path))return collectionPage(+path.split('/')[2]);if(path.startsWith('/profile/'))return profilePage(decodeURIComponent(location.pathname.slice(9)));if(path==='/settings')return settings();if(path==='/admin')return admin();if(path==='/my/posts')return listing({scope:'mine',title:'Мои публикации'});if(path==='/my/drafts')return listing({scope:'drafts',title:'Черновики'});if(path==='/my/saved')return listing({scope:'saved',title:'Сохранённое'});if(path==='/my/collections')return collectionsPage(true);if(path==='/my/applications')return applications();if(path==='/my/reports')return myReports();throw Error('Страница не найдена')}
(async()=>{try{state=await api('/api/session');user=state.user;csrf=state.csrf;const data=await api('/api/subjects');subjects=data.subjects;topics=data.topics;header();await route()}catch(e){$('#main').innerHTML=empty(e.message,'Проверьте адрес или вернитесь на главную.','/','На главную')}})();
